class Solution {
    public int titleToNumber(String columnTitle) {
        int value = 0;
        for (int i = 0; i < columnTitle.length(); i++) {
            int digit = columnTitle.charAt(i) - 'A' + 1;
            value = value * 26 + digit;
        }
        return value;
    }
}

class Solution {
    public int titleToNumber(String columnTitle) {
        int result = 0;
        int place = 1;
        for (int i = columnTitle.length() - 1; i >= 0; i--) {
            int digit = columnTitle.charAt(i) - 'A' + 1;
            result += digit * place;
            place *= 26;
        }
        return result;
    }
}

class Solution {
    public int titleToNumber(String columnTitle) {
        return fold(columnTitle, 0, 0);
    }

    private int fold(String title, int index, int value) {
        if (index == title.length()) {
            return value;
        }
        int digit = title.charAt(index) - 'A' + 1;
        return fold(title, index + 1, value * 26 + digit);
    }
}

class Solution {
    public int titleToNumber(String columnTitle) {
        int n = columnTitle.length();
        int[] powers = new int[n];
        powers[n - 1] = 1;
        for (int i = n - 2; i >= 0; i--) {
            powers[i] = powers[i + 1] * 26;
        }

        int result = 0;
        for (int i = 0; i < n; i++) {
            int digit = columnTitle.charAt(i) - 'A' + 1;
            result += digit * powers[i];
        }
        return result;
    }
}

class Solution {
    public int titleToNumber(String columnTitle) {
        int[] digitValue = new int[26];
        for (int i = 0; i < 26; i++) {
            digitValue[i] = i + 1;
        }

        int result = 0;
        for (int i = 0; i < columnTitle.length(); i++) {
            int digit = digitValue[columnTitle.charAt(i) - 'A'];
            result = result * 26 + digit;
        }
        return result;
    }
}
